void think_call(u8 think, objtype *ob)
{
    switch (think)
    {
    case TH_T_Stand: if (!SIGHT_SKIP(ob)) T_Stand(ob); break;
    case TH_T_Path: if (!tpath_fast(ob)) T_Path(ob); break;
    case TH_T_Chase: T_Chase(ob); break;
    case TH_T_DogChase: T_DogChase(ob); break;
    case TH_T_BJRun: T_BJRun(ob); break;
    case TH_T_BJJump: T_BJJump(ob); break;
    case TH_T_Player: T_Player(ob); break;
    case TH_T_Attack: T_Attack(ob); break;
    }
}

void action_call(u8 action, objtype *ob)
{
    switch (action)
    {
    case AC_T_Shoot: T_Shoot(ob); break;
    case AC_A_DeathScream: A_DeathScream(ob); break;
    case AC_T_Bite: T_Bite(ob); break;
    case AC_T_BJYell: T_BJYell(ob); break;
    case AC_T_BJDone: T_BJDone(ob); break;
    }
}
